@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  /* ──────────────────────────────────────────────────────────
     INKOS BRAND SWATCHES — Brand Book v1.0 (LOCKED)
     Bone · Onyx · Stone · Rust — no additions, no substitutes
  ────────────────────────────────────────────────────────── */
  --color-bone: #F7F7F5;
  --color-onyx: #0F0F0F;
  --color-stone: #787774;
  --color-rust: #B23A2B;

  --font-sans: var(--font-sans), 'Inter', -apple-system, sans-serif;
  --font-serif: var(--font-serif), 'Instrument Serif', Georgia, serif;
  --font-mono: var(--font-mono), 'JetBrains Mono', monospace;

  /* ──────────────────────────────────────────────────────────
     SEMANTIC PALETTE — derived from brand swatches
     Rule: never pure #FFF or #000. Bone/Onyx only.
  ────────────────────────────────────────────────────────── */

  /* Bone — 60% usage. Page canvas + sidebar bg. */
  --color-background: #F7F7F5;

  /* Onyx — 20% usage. Primary text + CTAs. */
  --color-foreground: #0F0F0F;

  /* Card surface — pure white on Bone, so cards "float" */
  --color-card: #FFFFFF;
  --color-card-foreground: #0F0F0F;

  --color-popover: #FFFFFF;
  --color-popover-foreground: #0F0F0F;

  /* Primary = Onyx (NOT Rust). Primary CTAs are black. */
  --color-primary: #0F0F0F;
  --color-primary-foreground: #F7F7F5;

  /* Secondary — muted Bone tint */
  --color-secondary: oklch(96% 0.003 60);
  --color-secondary-foreground: #0F0F0F;

  /* Muted — Stone-tinted backgrounds */
  --color-muted: oklch(95% 0.003 60);
  --color-muted-foreground: #787774;

  /* Accent — Rust at 12% opacity for active nav states */
  --color-accent: rgba(178, 58, 43, 0.08);
  --color-accent-foreground: #B23A2B;

  /* Destructive = Rust. Reserved for LIVE pill, active nav, destructive only. */
  --color-destructive: #B23A2B;
  --color-destructive-foreground: #F7F7F5;

  /* ──────────────────────────────────────────────────────────
     SEMANTIC STATUS TOKENS
  ────────────────────────────────────────────────────────── */
  --color-success:            oklch(58% 0.18 145);
  --color-success-bg:         oklch(94% 0.05 145);
  --color-success-foreground: oklch(26% 0.12 145);
  --color-warning:            oklch(70% 0.16 72);
  --color-warning-bg:         oklch(94% 0.07 72);
  --color-warning-foreground: oklch(36% 0.15 72);

  /* Borders — Stone-tinted, warm hue, tuned to be visible on bone canvas */
  --color-border: oklch(91% 0.005 85);
  --color-input: oklch(91% 0.005 85);
  --color-ring: #0F0F0F;

  /* ──────────────────────────────────────────────────────────
     SHADOWS — custom (never use Tailwind default shadow-sm/md)
  ────────────────────────────────────────────────────────── */

  /* Soft border shadow for cards on white — bumped alpha so cards read on bone bg */
  --shadow-soft: 0 1px 2px 0 oklch(20% 0.02 85 / 0.08), 0 1px 3px 0 oklch(20% 0.02 85 / 0.05);

  /* Standard card elevation — visible on off-white page */
  --shadow-card: 0 1px 3px 0 oklch(20% 0.02 85 / 0.10), 0 2px 4px -1px oklch(20% 0.02 85 / 0.06);

  /* Hover elevation */
  --shadow-card-hover: 0 6px 16px -4px oklch(20% 0.02 85 / 0.14), 0 3px 8px -2px oklch(20% 0.02 85 / 0.09);

  /* Medium depth for drawers, modals */
  --shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 85 / 0.10), 0 2px 8px -2px oklch(13% 0.015 85 / 0.07);

  /* Floating elements — command palette, toasts, tooltips */
  --shadow-lift: 0 8px 24px -4px oklch(13% 0.015 85 / 0.14),
                 0 4px 10px -2px oklch(13% 0.015 85 / 0.08);

  /* Full-screen overlays — modal backdrop shadow on dialog */
  --shadow-overlay: 0 24px 64px -12px oklch(13% 0.015 85 / 0.22),
                    0 8px 24px -4px oklch(13% 0.015 85 / 0.12);

  /* ──────────────────────────────────────────────────────────
     RADIUS
  ────────────────────────────────────────────────────────── */
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;   /* 24px — large modals, full-bleed cards */
  --radius-full: 9999px;  /* pill buttons, avatar chips, progress bars */

  /* ──────────────────────────────────────────────────────────
     TYPOGRAPHY
  ────────────────────────────────────────────────────────── */
  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;

  /* ──────────────────────────────────────────────────────────
     TYPOGRAPHY SCALE — semantic names
  ────────────────────────────────────────────────────────── */
  --text-display-size:    2.25rem;  /* 36px */
  --text-display-height:  2.5rem;   /* 40px */
  --text-display-weight:  700;
  --text-display-track:   -0.02em;

  --text-h1-size:    1.75rem;       /* 28px */
  --text-h1-height:  2rem;          /* 32px */
  --text-h1-weight:  700;
  --text-h1-track:   -0.015em;

  --text-h2-size:    1.25rem;       /* 20px */
  --text-h2-height:  1.75rem;       /* 28px */
  --text-h2-weight:  600;
  --text-h2-track:   -0.01em;

  --text-h3-size:    1rem;          /* 16px */
  --text-h3-height:  1.5rem;        /* 24px */
  --text-h3-weight:  600;
  --text-h3-track:   -0.005em;

  --text-body-size:    0.875rem;    /* 14px */
  --text-body-height:  1.25rem;     /* 20px */
  --text-body-weight:  400;
  --text-body-track:   0em;

  --text-body-sm-size:    0.8125rem; /* 13px */
  --text-body-sm-height:  1.125rem;  /* 18px */
  --text-body-sm-weight:  400;
  --text-body-sm-track:   0em;

  --text-caption-size:    0.75rem;  /* 12px */
  --text-caption-height:  1rem;     /* 16px */
  --text-caption-weight:  400;
  --text-caption-track:   0em;

  --text-micro-size:    0.625rem;   /* 10px */
  --text-micro-height:  0.875rem;   /* 14px */
  --text-micro-weight:  500;
  --text-micro-track:   0.06em;     /* uppercase tracking */

  /* ──────────────────────────────────────────────────────────
     SPACING CONSTANTS — semantic aliases
  ────────────────────────────────────────────────────────── */
  --spacing-page-x:      1.5rem;   /* px-6 — desktop page horizontal padding */
  --spacing-page-x-sm:   1rem;     /* px-4 — mobile page horizontal padding */
  --spacing-page-y:      1.5rem;   /* py-6 — vertical section gap */
  --spacing-card-pad:    1.5rem;   /* p-6  — card internal padding */
  --spacing-card-gap:    1rem;     /* gap-4 — gap between cards in a grid */
  --spacing-section-gap: 1.5rem;   /* space-y-6 — between page sections */
  --spacing-field-gap:   1rem;     /* space-y-4 — between form fields */

  /* ──────────────────────────────────────────────────────────
     ICON SIZE SCALE — reference constants (see lib/design-tokens.ts)
  ────────────────────────────────────────────────────────── */
  --icon-xs:  0.75rem;   /* 12px */
  --icon-sm:  0.875rem;  /* 14px */
  --icon-md:  1rem;      /* 16px */
  --icon-lg:  1.25rem;   /* 20px */
  --icon-xl:  1.5rem;    /* 24px */
  --icon-2xl: 2rem;      /* 32px */

  /* ──────────────────────────────────────────────────────────
     SIDEBAR TOKENS (shadcn sidebar primitives)
  ────────────────────────────────────────────────────────── */
  /* L0 — recessed chrome: ~2% deeper than L1 bone canvas so the sidebar reads
     as "behind" the content area. Premium SaaS elevation ladder. */
  --sidebar: oklch(95.5% 0.004 85);
  --sidebar-background: oklch(95.5% 0.004 85);
  --sidebar-foreground: #0F0F0F;
  --sidebar-primary: #0F0F0F;
  --sidebar-primary-foreground: #F7F7F5;
  --sidebar-accent: rgba(178, 58, 43, 0.10);
  --sidebar-accent-foreground: #B23A2B;
  --sidebar-border: oklch(91% 0.005 85);
  --sidebar-ring: #0F0F0F;
  --sidebar-width: 15rem;
  --sidebar-width-mobile: 18rem;
  --sidebar-width-icon: 3.5rem;

  /* shadcn token aliases */
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* ──────────────────────────────────────────────────────────
     PAGE LAYOUT — light mode
     Brand Book v1.0 — Bone/Stone/Onyx. Hue 85 = warm stone neutral.
     (was hue 264 = cool blue — fixed to remove subtle blue tint.)
  ────────────────────────────────────────────────────────── */
  --color-page-bg: oklch(97.5% 0.003 85);
  --color-header-bg: oklch(100% 0 0);
  --color-surface-1: oklch(100% 0 0);
  --color-surface-2: oklch(97.5% 0.003 85);

  /* ──────────────────────────────────────────────────────────
     STATUS BADGES — tattoo booking lifecycle
  ────────────────────────────────────────────────────────── */
  --color-status-pending: oklch(70% 0.16 72);
  --color-status-confirmed: oklch(62% 0.24 292);
  --color-status-in-progress: oklch(60% 0.2 200);
  --color-status-completed: oklch(58% 0.18 145);
  --color-status-cancelled: oklch(55% 0.02 85);
  --color-status-no-show: oklch(55% 0.22 27);

  /* ──────────────────────────────────────────────────────────
     NEON ACCENT
  ────────────────────────────────────────────────────────── */
  --color-neon-purple: oklch(72% 0.28 292);
  --color-neon-purple-glow: 0 0 20px oklch(72% 0.28 292 / 0.4);

  /* ──────────────────────────────────────────────────────────
     CONSENT — submission status colors (Sprint 5)
  ────────────────────────────────────────────────────────── */
  --color-consent-signed:       oklch(58% 0.18 145);
  --color-consent-pending:      oklch(70% 0.16 72);
  --color-consent-expired:      oklch(55% 0.02 85);
  --color-consent-deleted:      oklch(45% 0.02 85);
  --color-consent-opened:       oklch(60% 0.22 230);

  /* ──────────────────────────────────────────────────────────
     CONSENT — template kind badge colors
  ────────────────────────────────────────────────────────── */
  --color-kind-tattoo:   oklch(62% 0.24 292);
  --color-kind-piercing: oklch(60% 0.22 230);
  --color-kind-pmu:      oklch(60% 0.24 340);
  --color-kind-touchup:  oklch(70% 0.16 72);
  --color-kind-minor:    oklch(55% 0.22 27);

  /* ──────────────────────────────────────────────────────────
     CONSENT — signature pad
  ────────────────────────────────────────────────────────── */
  --color-sig-bg:              oklch(6% 0.01 85);
  --color-sig-stroke:          oklch(97% 0.01 85);
  --color-sig-border:          oklch(28% 0.04 292);
  --color-sig-border-active:   oklch(62% 0.24 292 / 0.6);

