/* ──────────────────────────────────────────────────────────
   DARK MODE — single authoritative .dark block (Sprint 4)
   Philosophy: Linear/Notion dark — NOT pitch black.
   Background L15, card L20, border L28. Warm slate hue 264.
────────────────────────────────────────────────────────── */
.dark {
  /* ── Core semantic ── */
  --color-background:          oklch(15% 0.01 85);
  --color-foreground:          oklch(95% 0.005 85);
  --color-card:                oklch(20% 0.015 85);
  --color-card-foreground:     oklch(95% 0.005 85);
  --color-popover:             oklch(20% 0.015 85);
  --color-popover-foreground:  oklch(95% 0.005 85);

  --color-primary:             oklch(65% 0.24 292);
  --color-primary-foreground:  oklch(99% 0 0);

  --color-secondary:           oklch(24% 0.015 85);
  --color-secondary-foreground: oklch(88% 0.01 85);

  --color-muted:               oklch(22% 0.01 85);
  --color-muted-foreground:    oklch(66% 0.015 85);   /* raised from 60 → 66 for AA on body text */

  --color-accent:              oklch(25% 0.035 292);
  --color-accent-foreground:   oklch(78% 0.14 292);

  --color-destructive:         oklch(62% 0.22 27);     /* L62 for 4.7:1 on bg */
  --color-destructive-foreground: oklch(99% 0 0);

  /* Brand Book v1.0 — dark onyx surfaces use warm neutral hue (85). */
  --color-border:              oklch(22% 0.008 85);
  --color-input:               oklch(20% 0.007 85);
  --color-ring:                oklch(58% 0.16 35); /* rust accent */

  /* ── Surfaces (elevation ladder) ── */
  --color-page-bg:             oklch(14% 0.005 85);
  --color-header-bg:           oklch(13% 0.006 85 / 0.85);
  --color-surface-1:           oklch(20% 0.007 85);
  --color-surface-2:           oklch(24% 0.006 85);
  --color-surface-3:           oklch(28% 0.005 85);
  --color-surface-elevated:    oklch(30% 0.007 85);

  /* ── Shadows (stronger alpha — dark bg absorbs shadow) ── */
  --shadow-soft:       0 1px 3px oklch(0% 0 0 / 0.3), 0 1px 2px -1px oklch(0% 0 0 / 0.22);
  --shadow-card:       0 1px 4px oklch(0% 0 0 / 0.25), 0 2px 8px -2px oklch(0% 0 0 / 0.2);
  --shadow-card-hover: 0 8px 25px oklch(0% 0 0 / 0.35), 0 0 0 1px oklch(65% 0.24 292 / 0.2), inset 0 1px 0 oklch(100% 0 0 / 0.05);
  --shadow-soft-md:    0 4px 12px -2px oklch(0% 0 0 / 0.3), 0 2px 6px -2px oklch(0% 0 0 / 0.2);
  --shadow-lift:       0 8px 24px -4px oklch(0% 0 0 / 0.55), 0 4px 10px -2px oklch(0% 0 0 / 0.35);
  --shadow-overlay:    0 24px 64px -12px oklch(0% 0 0 / 0.75), 0 8px 24px -4px oklch(0% 0 0 / 0.5);
  --shadow-glow-card:  0 1px 3px oklch(0% 0 0 / 0.2), 0 0 0 1px oklch(28% 0.02 85 / 0.6), inset 0 1px 0 oklch(100% 0 0 / 0.04);
  --shadow-glow-purple: 0 0 0 1px oklch(65% 0.24 292 / 0.2), 0 0 20px oklch(65% 0.24 292 / 0.1);

  /* ── Status tokens ── */
  --color-success:             oklch(62% 0.18 145);
  --color-success-bg:          oklch(20% 0.06 145);
  --color-success-foreground:  oklch(82% 0.12 145);
  --color-warning:             oklch(72% 0.16 72);
  --color-warning-bg:          oklch(22% 0.07 72);
  --color-warning-foreground:  oklch(86% 0.12 72);

  /* ── KPI accent borders ── */
  --color-kpi-bookings:        oklch(65% 0.24 292);
  --color-kpi-revenue:         oklch(62% 0.18 145);
  --color-kpi-clients:         oklch(63% 0.22 230);
  --color-kpi-alert:           oklch(58% 0.22 27);

  /* ── Auth page surfaces ── */
  --color-auth-bg:             oklch(12% 0.015 85);
  --color-auth-card:           oklch(18% 0.015 85);
  --color-auth-border:         oklch(28% 0.03 85);

  /* ── Sidebar — L0 recessed (deeper than page-bg 14% so chrome reads behind content) ── */
  --sidebar:                        oklch(11% 0.006 85);
  --sidebar-background:             oklch(11% 0.006 85);
  --sidebar-foreground:             oklch(88% 0.01 85);
  --sidebar-primary:                oklch(65% 0.24 292);
  --sidebar-primary-foreground:     oklch(99% 0 0);
  --sidebar-accent:                 oklch(24% 0.035 292);
  --sidebar-accent-foreground:      oklch(78% 0.14 292);
  --sidebar-border:                 oklch(22% 0.008 85);
  --sidebar-ring:                   oklch(65% 0.24 292);
  --color-sidebar:                  var(--sidebar);
  --color-sidebar-foreground:       var(--sidebar-foreground);
  --color-sidebar-primary:          var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent:           var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border:           var(--sidebar-border);
  --color-sidebar-ring:             var(--sidebar-ring);

  /* ── Skeleton shimmer override ── */
  --shimmer-highlight:         oklch(100% 0 0 / 0.04);
}

/* ──────────────────────────────────────────────────────────
   REDUCED MOTION — disable transforms, keep opacity fades
────────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  /* Allow opacity-only fades at full duration — these are safe */
  .motion-safe-fade {
    animation-duration: var(--duration-base) !important;
    transition-duration: var(--duration-base) !important;
  }
}

@layer utilities {
  /* ─── SKELETON BASE UTILITIES ─── */
  .skeleton-block {
    background-color: var(--shimmer-bg);
    animation: shimmer-base var(--shimmer-duration) var(--ease-linear) infinite;
    border-radius: var(--radius-sm);
  }

  .skeleton-sweep {
    background-image: linear-gradient(
      90deg,
      transparent 0%,
      var(--shimmer-highlight) 50%,
      transparent 100%
    );
    background-size: 200% 100%;
    animation:
      shimmer-base var(--shimmer-duration) var(--ease-linear) infinite,
      shimmer-sweep var(--shimmer-duration) var(--ease-linear) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    .skeleton-block,
    .skeleton-sweep {
      animation: none;
      opacity: 0.7;
    }
  }

  /* ─── LIFT archetype — KpiCard, StatCard, interactive feature cards ─── */
  .hover-lift {
    transition:
      transform var(--duration-fast) var(--ease-standard),
      box-shadow var(--duration-fast) var(--ease-standard);
  }
  .hover-lift:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-card-hover);
  }
  .hover-lift:active {
    transform: translateY(0px);
    transition-duration: var(--duration-instant);
  }

  @media (prefers-reduced-motion: reduce) {
    .hover-lift:hover {
      transform: none;
      box-shadow: none;
      background-color: color-mix(in oklch, currentColor 3%, transparent);
    }
  }

  /* ─── TINT archetype — DataTable rows, MenuItem, NavItem, FilterBar ─── */
  .hover-tint {
    transition: background-color var(--duration-instant) var(--ease-standard);
  }
  .hover-tint:hover {
    background-color: color-mix(in oklch, var(--color-foreground) 4%, transparent);
  }
  .hover-tint:active {
    background-color: color-mix(in oklch, var(--color-foreground) 6%, transparent);
    transition-duration: calc(var(--duration-instant) / 2);
  }

  /* ─── BUTTON PRESS — scale + darken (Nova §4 convergence) ─── */
  .press-scale {
    transition:
      transform var(--duration-instant) var(--ease-standard),
      background-color var(--duration-instant) var(--ease-standard);
  }
  .press-scale:active {
    transform: scale(0.97);
    background-color: color-mix(in oklch, var(--btn-bg, var(--color-primary)) 92%, black);
  }

  @media (prefers-reduced-motion: reduce) {
    .press-scale:active { transform: none; }
  }

  /* ─── FOCUS RING — universal, :focus-visible only ─── */
  .focus-ring {
    transition: outline var(--duration-base) var(--ease-standard);
  }
  .focus-ring:focus-visible {
    outline: 2px solid var(--color-electric-purple);
    outline-offset: 2px;
    border-radius: inherit;
  }

  /* ─── VIEW TRANSITIONS ─── */
  ::view-transition-old(root) {
    animation:
      var(--duration-page) var(--ease-emphasized) both crossfade-out;
  }
  ::view-transition-new(root) {
    animation:
      var(--duration-page) var(--ease-standard) both crossfade-in;
  }

  @keyframes crossfade-out {
    from { opacity: 1; transform: translateY(0); }
    to   { opacity: 0; transform: translateY(6px); }
  }
  @keyframes crossfade-in {
    from { opacity: 0; transform: translateY(-6px); }
    to   { opacity: 1; transform: translateY(0); }

