  }

  @media (prefers-reduced-motion: reduce) {
    ::view-transition-old(root),
    ::view-transition-new(root) {
      animation: none;
    }
  }

  /* ─── OPTIMISTIC UI — reorder error pulse ─── */
  [data-reorder-error='true'] {
    animation: rollback-pulse 300ms var(--ease-standard) 2;
    outline: 2px solid var(--color-destructive);
    outline-offset: 2px;
  }

  /* ─── REDUCED MOTION DEMO OVERRIDE (dev/design page only) ─── */
  .motion-safe-override * {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

@layer components {
  /* ── Sidebar active state — pill glow, no border-shift ── */
  [data-sidebar="menu-button"][data-active="true"] {
    background-color: oklch(62% 0.24 292 / 0.1);
    color: oklch(80% 0.14 292);
    position: relative;
  }
  [data-sidebar="menu-button"][data-active="true"]::before {
    content: '';
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
    width: 3px;
    height: 60%;
    border-radius: 0 3px 3px 0;
    background: oklch(72% 0.22 292);
    box-shadow: 0 0 8px oklch(62% 0.24 292 / 0.6);
  }
  [data-sidebar="menu-button"][data-active="true"] svg {
    color: oklch(72% 0.22 292);
    opacity: 1;
  }
  [data-sidebar="menu-button"][data-active="true"]:hover {
    background-color: oklch(62% 0.24 292 / 0.15);
  }

  /* ── Status badge variants ── */
  .badge-pending     { background-color: oklch(70% 0.16 72 / 0.12); color: oklch(70% 0.16 72); }
  .badge-confirmed   { background-color: oklch(62% 0.24 292 / 0.12); color: oklch(75% 0.18 292); }
  .badge-in-progress { background-color: oklch(60% 0.2 200 / 0.12); color: oklch(60% 0.2 200); }
  .badge-completed   { background-color: oklch(58% 0.18 145 / 0.12); color: oklch(58% 0.18 145); }
  .badge-cancelled   { background-color: oklch(55% 0.02 85 / 0.12); color: oklch(60% 0.02 85); }
  .badge-no-show     { background-color: oklch(55% 0.22 27 / 0.12); color: oklch(65% 0.2 27); }

  /* ── FullCalendar dark theme override ── */
  :root {
    --fc-border-color: oklch(22% 0.02 85);
    --fc-daygrid-event-dot-width: 8px;
    --fc-today-bg-color: oklch(62% 0.24 292 / 0.06);
    --fc-now-indicator-color: oklch(62% 0.24 292);
    --fc-non-business-color: oklch(14% 0.015 85 / 0.5);
    --fc-bg-event-color: oklch(62% 0.24 292);
    --fc-highlight-color: oklch(62% 0.24 292 / 0.08);
    --fc-page-bg-color: transparent;
    --fc-neutral-bg-color: oklch(14% 0.015 85);
    --fc-neutral-text-color: oklch(65% 0.01 85);
    --fc-list-event-hover-bg-color: oklch(18% 0.02 85);
    --fc-small-font-size: 0.8em;
  }
  .fc .fc-toolbar-title {
    font-size: 1rem;
    font-weight: 600;
    letter-spacing: -0.01em;
  }
  .fc .fc-button {
    background: oklch(18% 0.02 85);
    border: 1px solid oklch(25% 0.02 85);
    color: oklch(70% 0.01 85);
    border-radius: var(--radius);
    font-size: 0.8125rem;
    padding: 0.375rem 0.75rem;
    transition: background 150ms ease-out, color 150ms ease-out;
  }
  .fc .fc-button:hover {
    background: oklch(24% 0.02 85);
    color: oklch(90% 0.01 85);
  }
  .fc .fc-button-primary:not(:disabled).fc-button-active {
    background: oklch(62% 0.24 292 / 0.15);
    color: oklch(75% 0.18 292);
    border-color: oklch(62% 0.24 292 / 0.3);
  }
  .fc-timegrid-slot {
    height: var(--calendar-slot-height);
  }
  .fc-event {
    border-radius: var(--calendar-event-border-radius);
    border-width: 0;
    border-left-width: 3px;
    font-size: 0.75rem;
    padding: 0.125rem 0.375rem;
    cursor: pointer;
  }
  .fc-event-dragging {
    opacity: 0.75;
    box-shadow: 0 8px 24px oklch(0% 0 0 / 0.5);
  }
  .fc-event-selected {
    box-shadow: 0 0 0 2px var(--color-primary);
  }
  .fc .fc-toolbar {
    display: none;
  }

  /* ── FullCalendar: now-indicator ── */
  .fc .fc-timegrid-now-indicator-line {
    border-color: var(--color-primary);
    border-width: 2px;
  }
  .fc .fc-timegrid-now-indicator-arrow {
    border-top-color: var(--color-primary);
    border-bottom-color: var(--color-primary);
  }

  /* ── FullCalendar: event hover ── */
  .fc-event:hover {
    filter: brightness(1.1);
    transition: filter 100ms ease-out;
  }

  /* ── FullCalendar: "+N more" link ── */
  .fc .fc-daygrid-more-link {
    color: var(--color-primary);
    font-size: 0.6875rem;
    font-weight: 500;
  }
  .fc .fc-daygrid-more-link:hover {
    color: var(--color-primary);
    text-decoration: underline;
    opacity: 0.8;
  }

  /* ── FullCalendar: list view ── */
  .fc .fc-list-event:hover td {
    background: color-mix(in oklch, var(--color-primary) 6%, transparent);
  }
  .fc .fc-list-day-cushion {
    background: color-mix(in oklch, var(--color-primary) 5%, transparent);
  }

  /* ── Calendar shortcut hint bar ── */
  .calendar-shortcuts-bar {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    flex-wrap: wrap;
    padding: 0.375rem 1rem;
    background: color-mix(in oklch, var(--color-primary) 4%, transparent);
    border-bottom: 1px solid color-mix(in oklch, var(--color-primary) 12%, transparent);
    font-size: 0.6875rem;
    color: var(--color-muted-foreground);
  }
  .calendar-shortcut-key {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.25rem;
    height: 1.25rem;
    padding: 0 0.25rem;
    background: var(--color-muted);
    border: 1px solid var(--color-border);
    border-radius: 0.25rem;
    font-family: var(--font-mono);
    font-size: 0.625rem;
    font-weight: 500;
    color: var(--color-muted-foreground);
  }

  /* ── Calendar: print ── */
  @media print {
    .calendar-toolbar,
    .calendar-filter-row,
    .calendar-shortcuts-bar,
    .fc-toolbar,
    .fc-scroller-harness > .fc-scroller {
      overflow: visible !important;
    }
    .fc-view-harness {
      height: auto !important;
    }
    .fc-timegrid-event .fc-event-main {
      white-space: normal;
    }
    /* Hide nav/sidebar in print */
    [data-sidebar],
    nav,
    aside {
      display: none !important;
    }
    .fc-event {
      border: 1px solid currentColor !important;
      break-inside: avoid;
    }
    .artist-event-1,
    .artist-event-2,
    .artist-event-3,
    .artist-event-4,
    .artist-event-5,
    .artist-event-6,
    .artist-event-7,
    .artist-event-8,
    .artist-event-9,
    .artist-event-10 {
      print-color-adjust: exact;
      -webkit-print-color-adjust: exact;
    }

