async function handleSignOut() {
  await supabase.auth.signOut()
  router.push('/login')
  router.refresh()
}

return (
  <SidebarInset className="flex flex-col">
    <header className="sticky top-0 z-40 flex h-14 shrink-0 items-center gap-3 border-b border-border bg-[var(--color-header-bg)]/85 px-4 backdrop-blur-md supports-[backdrop-filter]:bg-[var(--color-header-bg)]/75">
      <div className="flex min-w-0 flex-1 items-center gap-2">
        <MobileNav
          userName={userName}
          userEmail={userEmail ?? ''}
          userAvatarUrl={userAvatarUrl}
          studioName={studioName}
          {...(studioSlug !== undefined ? { studioSlug } : {})}
          role={role}
          plan={plan}
          locationCount={allLocations.length}
          permissionKeys={permissionKeys}
          {...(dynamicBadges !== undefined ? { dynamicBadges } : {})}
          onSignOut={handleSignOut}
          open={mobileNavOpen}
          onOpenChange={setMobileNavOpen}
          allMemberships={allMemberships}

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

interface PageShellProps {
  children: ReactNode
  /**
   * Opt out of default padding for full-height layouts (Calendar, Messages).
   * The page is responsible for its own scroll container + internal padding.
   */
  fullHeight?: boolean
  /** Max content width cap. Default `1440`. Pass `false` to disable the cap. */
  maxWidth?: number | false
  /** Extra classes applied to the outer wrapper. */
  className?: string
  /** Extra classes applied to the inner padded container (ignored when fullHeight). */
  innerClassName?: string
}

/**
 * S18 — Branded page container.
 *
 * Enforces the same gutter + vertical rhythm the TodayClient established as the
 * gold standard: `px-4 sm:px-6 lg:px-8 pt-6 pb-10`, `max-w-[1440px]` cap,
 * background token `--color-page-bg`. Every authenticated page should wrap its
 * content in `<PageShell>`. Full-height layouts (Calendar, Messages) pass
 * `fullHeight` to skip the default padding and handle scroll internally.
 */
export function PageShell({
  children,
  fullHeight = false,
  maxWidth = 1440,
  className,
  innerClassName,
}: PageShellProps) {
  if (fullHeight) {
    return (
      <div className={cn('flex min-h-0 flex-1 flex-col', className)}>
        {children}
      </div>
    )
  }

  return (
    <div
      className={cn(
        // Base bone background, plus a soft warm radial highlight drifting from
        // the top-right. Gives the page tonal depth without overwhelming content.
        'relative flex min-h-full flex-col bg-[var(--color-page-bg)]',
        'before:pointer-events-none before:absolute before:inset-0',
        'before:bg-[radial-gradient(ellipse_at_top_right,_oklch(98%_0.008_65/_0.9)_0%,_transparent_55%)]',
        // Faint bottom-left rust whisper — brand accent, barely visible (<3% alpha)
        'after:pointer-events-none after:absolute after:inset-0',
        'after:bg-[radial-gradient(circle_at_bottom_left,_oklch(58%_0.16_35/_0.025)_0%,_transparent_45%)]',
        className,
      )}
    >
      <div
        style={
          maxWidth !== false && maxWidth !== 1440
            ? { maxWidth: `${maxWidth}px` }
            : undefined
        }
        className={cn(
          'relative z-10 mx-auto w-full flex-1 px-4 pb-10 pt-6 sm:px-6 lg:px-8',
          maxWidth === 1440 && 'max-w-[1440px]',
          innerClassName,
        )}
      >
        {children}
      </div>
    </div>
  )
}

