            <li
              key={step.id}
              className={cn(
                'flex items-start gap-3 group',
                step.done && 'opacity-60',
              )}
              style={{
                animationDelay: `${idx * 60}ms`,
                animationFillMode: 'both',
              }}
            >
              {step.done ? (
                <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-[hsl(var(--color-electric-purple))]" />
              ) : (
                <Circle className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground/40" />
              )}
              <div className="flex-1 min-w-0">
                <Link
                  href={step.href}
                  className={cn(
                    'text-sm font-medium leading-none hover:underline underline-offset-2 transition-colors',
                    step.done
                      ? 'line-through text-muted-foreground'
                      : 'text-foreground group-hover:text-primary',
                  )}
                >
                  {step.label}
                </Link>
                {!step.done && (
                  <p className="mt-0.5 text-xs text-muted-foreground leading-snug">
                    {step.description}
                  </p>
                )}
              </div>
              {!step.done && (
                <Link
                  href={step.href}
                  className="h-6 px-2 text-xs shrink-0 opacity-0 group-hover:opacity-100 transition-opacity inline-flex items-center rounded-md hover:bg-muted text-muted-foreground hover:text-foreground"
                >
                  Go →
                </Link>
              )}
            </li>
          ))}
        </ol>
      </div>
    </div>
  )
}

