import { Calendar, MapPin } from 'lucide-react'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'

const STYLE_LABELS: Record<string, string> = {
  blackwork: 'Blackwork', watercolor: 'Watercolor', traditional: 'Traditional',
  neo_trad: 'Neo Traditional', realism: 'Realism', geometric: 'Geometric',
  minimalist: 'Minimalist', japanese: 'Japanese', tribal: 'Tribal',
  trash_polka: 'Trash Polka', dotwork: 'Dotwork', illustrative: 'Illustrative',
  abstract: 'Abstract', lettering: 'Lettering', other: 'Other',
}

interface ShareData {
  studioName: string
  studioSlug?: string | null
  studioLogoUrl: string | null
  brandColor: string | null
  styleCategory: string
  bodyArea: string | null
  description: string
  imageUrl: string | null  // signed URL
  signedAt: string
}

interface Props {
  data: ShareData
}

export function ShareDesignPage({ data }: Props) {
  const accentColor = data.brandColor ?? 'var(--color-electric-purple)'

  return (
    <div className="min-h-screen bg-background">
      {/* Studio header */}
      <header
        className="border-b border-border/60 px-6 py-4"
        style={{ borderBottomColor: `${accentColor}20` }}
      >
        <div className="mx-auto flex max-w-2xl items-center justify-between">
          <div className="flex items-center gap-3">
            {data.studioLogoUrl ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={data.studioLogoUrl}
                alt={data.studioName}
                className="h-8 w-8 rounded-full object-cover"
              />
            ) : (
              <div
                className="flex h-8 w-8 items-center justify-center rounded-full text-xs font-bold text-white"
                style={{ backgroundColor: accentColor }}
              >
                {data.studioName.charAt(0).toUpperCase()}
              </div>
            )}
            <span className="text-sm font-semibold">{data.studioName}</span>
          </div>
          <span className="text-[11px] text-muted-foreground">Design concept</span>
        </div>
      </header>

      {/* Main content */}
      <main className="mx-auto max-w-2xl px-6 py-8 space-y-6">
        {/* Generated image */}
        {data.imageUrl ? (
          <div className="overflow-hidden rounded-2xl border border-border shadow-soft-md">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={data.imageUrl}
              alt={`${STYLE_LABELS[data.styleCategory] ?? data.styleCategory} tattoo design concept`}
              className="w-full object-cover"
            />
          </div>
        ) : (
          <div className="flex aspect-square items-center justify-center rounded-2xl border border-dashed border-border bg-muted/30">
            <p className="text-xs text-muted-foreground">Image not available</p>
          </div>
        )}

        {/* Design details */}
        <div className="space-y-4">
          <div className="flex flex-wrap items-center gap-2">
            <Badge variant="secondary" className="text-xs">
              {STYLE_LABELS[data.styleCategory] ?? data.styleCategory}
            </Badge>
            {data.bodyArea && (
              <span className="flex items-center gap-1 text-xs text-muted-foreground">
                <MapPin size={11} strokeWidth={1.75} />
                {data.bodyArea}
              </span>
            )}
          </div>

          <div className="rounded-xl bg-muted/40 p-4">
            <p className="text-sm leading-relaxed text-foreground">{data.description}</p>
          </div>

          <div className="flex items-center gap-1.5 text-[11px] text-muted-foreground">
            <Calendar size={11} strokeWidth={1.75} />
            Shared {new Date(data.signedAt).toLocaleDateString('en-US', {
              year: 'numeric', month: 'long', day: 'numeric',
            })}
          </div>
        </div>

        {/* CTA */}
        <div
          className="rounded-2xl p-6 text-center space-y-3"
          style={{ backgroundColor: `${accentColor}10`, borderColor: `${accentColor}30`, border: '1px solid' }}
        >
          <p className="text-sm font-semibold" style={{ color: accentColor }}>
            Love this design?
          </p>
          <p className="text-xs text-muted-foreground">
            Book a consultation with {data.studioName} to bring it to life.
          </p>
          {data.studioSlug ? (
            <Button
              size="sm"
              style={{ backgroundColor: accentColor }}
              className="text-white hover:opacity-90"
              render={<Link href={`/book/${data.studioSlug}`} />}
            >
              Book a consultation
            </Button>
          ) : (
            <Button
              size="sm"
              style={{ backgroundColor: accentColor }}
              className="text-white hover:opacity-90"
              render={<a href={`mailto:studio@inkos.app?subject=Booking%20consultation%20%E2%80%94%20${encodeURIComponent(data.studioName)}`} />}
            >
              Contact {data.studioName}
            </Button>
          )}
        </div>

        {/* Watermark */}
        <p className="text-center text-[10px] text-muted-foreground/60">
          AI-generated concept by InkOS · For internal use only
        </p>
      </main>
    </div>
  )
}

