              isFirst && 'opacity-40 cursor-not-allowed'
            )}
            aria-label="Move up"
          >
            <ChevronUp className="h-3 w-3" />
          </button>
          <button
            onClick={onMoveDown}
            disabled={isLast}
            className={cn(
