'use client'

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import { Camera, Trash2 } from 'lucide-react'
import { FileDropzone } from '@/components/ui/file-dropzone'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { addProgressPhotoAction, removeProgressPhotoAction } from '@/app/(app)/projects/actions'
import type { ProjectWithSessions, ProjectProgressPhoto, ProjectPhotoKind } from '@/lib/projects/queries'

interface ProgressTabProps {
  project: ProjectWithSessions
  photos: ProjectProgressPhoto[]
  role: string
  onRefresh: () => void
}

const PHOTO_KINDS: { kind: ProjectPhotoKind; label: string; description: string }[] = [
  { kind: 'before', label: 'Before', description: 'Pre-tattoo skin reference' },
  { kind: 'after', label: 'After', description: 'Immediately after each session' },
  { kind: 'healed', label: 'Healed', description: 'Fully healed result' },
  { kind: 'progress', label: 'Progress', description: 'Mid-session / work in progress' },
]

export function ProgressTab({ project, photos, role, onRefresh }: ProgressTabProps) {
  const [isPending, startTransition] = useTransition()
  const [removingId, setRemovingId] = useState<string | null>(null)
  const [uploadingKind, setUploadingKind] = useState<ProjectPhotoKind | null>(null)

  const canWrite = role === 'owner' || role === 'admin' || role === 'artist'

  const handleUpload = (kind: ProjectPhotoKind, files: File[]) => {
    const file = files[0]
    if (!file) return

    setUploadingKind(kind)
    startTransition(async () => {
      const fd = new FormData()
      fd.append('file', file)
      fd.set('kind', kind)
      const result = await addProgressPhotoAction(project.id, fd)
      setUploadingKind(null)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success(`${kind.charAt(0).toUpperCase() + kind.slice(1)} photo added`)
      onRefresh()
    })
  }

  const handleRemove = (photoId: string) => {
    startTransition(async () => {
      const result = await removeProgressPhotoAction(project.id, photoId)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Photo removed')
      onRefresh()
    })
    setRemovingId(null)
  }

  return (
    <div className="space-y-8 max-w-3xl">
      {PHOTO_KINDS.map(({ kind, label, description }) => {
        const kindPhotos = photos.filter((p) => p.kind === kind)
        const isUploadingThis = uploadingKind === kind

        return (
          <section key={kind}>
            <div className="flex items-center justify-between mb-3">
              <div>
                <h3 className="text-sm font-semibold text-foreground">{label}</h3>
                <p className="text-xs text-muted-foreground">{description}</p>
              </div>
              {canWrite && (
                <div className="shrink-0 w-40">
                  <FileDropzone
                    accept={{ 'image/*': ['.jpg', '.jpeg', '.png', '.webp'] }}
                    maxSize={10 * 1024 * 1024}
                    maxFiles={1}
                    onFilesAccepted={(files) => handleUpload(kind, files)}
                    loading={isUploadingThis}
                    disabled={isPending}
                    className="h-auto py-2 text-xs"
                  >
                    <div className="flex items-center gap-1.5 text-muted-foreground">
                      <Camera className="h-3.5 w-3.5" />
                      <span className="text-xs">Upload photo</span>
                    </div>
                  </FileDropzone>
                </div>
              )}
            </div>

            {kindPhotos.length === 0 ? (
              <div className="flex items-center justify-center h-20 rounded-lg border border-dashed border-border text-xs text-muted-foreground">
                No {label.toLowerCase()} photos yet
              </div>
            ) : (
              <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-thin scrollbar-thumb-border">
                {kindPhotos.map((photo) => (
                  <PhotoTile
                    key={photo.id}
                    photo={photo}
                    canWrite={canWrite}
                    onRemove={() => setRemovingId(photo.id)}
                  />
                ))}
              </div>
            )}
          </section>
        )
      })}

      {/* Remove confirmation */}
      <AlertDialog
        open={removingId !== null}
        onOpenChange={(open) => !open && setRemovingId(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove this photo?</AlertDialogTitle>
            <AlertDialogDescription>
              The photo will be permanently removed. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => removingId && handleRemove(removingId)}
              disabled={isPending}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Remove
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

