      {canWrite && (
        <button
          onClick={onRemove}
          className="absolute top-1 right-1 p-1 rounded bg-black/40 text-white hover:bg-destructive transition-colors opacity-0 group-hover:opacity-100"
          aria-label="Remove photo"
        >
          <Trash2 className="h-2.5 w-2.5" />
        </button>
      )}
