'use client'

import { useEffect, useState } from 'react'
import { CheckCircle2 } from 'lucide-react'
import { StepStudioProfile } from './StepStudioProfile'
import { StepFirstLocation } from './StepFirstLocation'
import { StepFirstArtist } from './StepFirstArtist'
import { StepFirstService } from './StepFirstService'
import { StepBookingPageLive } from './StepBookingPageLive'

interface OnboardingWizardProps {
  studioId: string | null
  userId: string
}

const TOTAL_STEPS = 5
const STORAGE_KEY = 'inkos-onboarding-step'

const STEP_LABELS = [
  'Studio',
  'Location',
  'Artist',
  'Service',
  'Go live',
]

function StepIndicator({
  current,
  total,
}: {
  current: number
  total: number
}) {
  return (
    <div className="mb-8">
      <div className="flex items-center gap-1">
        {Array.from({ length: total }).map((_, i) => {
          const stepNum = i + 1
          const isDone = stepNum < current
          const isActive = stepNum === current

          return (
            <div key={i} className="flex flex-1 items-center">
              <div className="flex flex-col items-center">
                <div
                  aria-current={isActive ? 'step' : undefined}
                  className={[
                    'flex h-8 w-8 items-center justify-center rounded-full text-xs font-semibold transition-all',
                    isDone ? 'onboarding-step-done text-white' : '',
                    isActive ? 'onboarding-step-active text-white' : '',
                    !isDone && !isActive ? 'onboarding-step-future text-muted-foreground' : '',
                  ].join(' ')}
                >
                  {isDone ? (
                    <CheckCircle2 className="h-4 w-4" aria-hidden="true" />
                  ) : (
                    stepNum
                  )}
                </div>
                <span className="mt-1 hidden text-[10px] text-muted-foreground sm:block">
                  {STEP_LABELS[i]}
                </span>
              </div>

              {i < total - 1 && (
                <div
                  className={[
                    'mx-1 h-px flex-1',
                    isDone ? 'bg-success/60' : 'bg-border',
                  ].join(' ')}
                  aria-hidden="true"
                />
              )}
            </div>
          )
        })}

        <span className="ml-4 shrink-0 text-xs text-muted-foreground">
          Step {current} of {total}
        </span>
      </div>
    </div>
  )
}

export function OnboardingWizard({ studioId, userId }: OnboardingWizardProps) {
  const [startTime] = useState<number>(() => Date.now())

  const [currentStep, setCurrentStep] = useState<number>(() => {
    if (typeof window === 'undefined') return 1
    const saved = localStorage.getItem(STORAGE_KEY)
    const parsed = saved ? parseInt(saved, 10) : NaN
    return Number.isFinite(parsed) && parsed >= 1 && parsed <= TOTAL_STEPS ? parsed : 1
  })

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, String(currentStep))
  }, [currentStep])

  function goNext() {
    setCurrentStep((prev) => Math.min(prev + 1, TOTAL_STEPS))
  }

  function goBack() {
    setCurrentStep((prev) => Math.max(prev - 1, 1))
  }

  return (
    <div className="w-full overflow-hidden rounded-xl border border-border/50 bg-card shadow-[var(--shadow-soft-md)]">
      <div className="h-[3px] w-full bg-primary" />
      <div className="p-8">
        {/* InkOS wordmark */}
        <div className="mb-6 flex items-center gap-2">
          <div className="flex h-6 w-6 items-center justify-center rounded bg-primary">
            <span className="text-[10px] font-bold text-primary-foreground">IO</span>
          </div>
          <span className="text-sm font-semibold tracking-tight">InkOS</span>
        </div>

        <StepIndicator current={currentStep} total={TOTAL_STEPS} />

        {currentStep === 1 && (
          <StepStudioProfile studioId={studioId} onNext={goNext} />
        )}
        {currentStep === 2 && (
          <StepFirstLocation studioId={studioId} onNext={goNext} onBack={goBack} onSkip={goNext} />
        )}
        {currentStep === 3 && (
          <StepFirstArtist
            studioId={studioId}
            userId={userId}
            onNext={goNext}
            onBack={goBack}
            onSkip={goNext}
          />
        )}
        {currentStep === 4 && (
          <StepFirstService studioId={studioId} onNext={goNext} onBack={goBack} onSkip={goNext} />
        )}
        {currentStep === 5 && (
          <StepBookingPageLive
            studioId={studioId}
            startTime={startTime}
            onBack={goBack}
          />
        )}
      </div>
    </div>
  )
}

'use client'

import { cn } from '@/lib/utils'
import { Check } from 'lucide-react'

interface Step {
  label: string
}

interface BookingStepIndicatorProps {
  steps: Step[]
  currentStep: number
  className?: string
}

export function BookingStepIndicator({
  steps,
  currentStep,
  className,
}: BookingStepIndicatorProps) {
  return (
    <nav aria-label="Booking progress" className={cn('flex items-center gap-0', className)}>
      {steps.map((step, index) => {
        const isDone = index < currentStep
        const isActive = index === currentStep
        const isFuture = index > currentStep

        return (
          <div key={step.label} className="flex items-center">
            <div className="flex flex-col items-center gap-1">
              <div
                aria-current={isActive ? 'step' : undefined}
                className={cn(
                  'flex h-7 w-7 items-center justify-center rounded-full text-xs font-semibold transition-all duration-200',
                  isDone && 'timeline-step-done bg-[var(--color-timeline-dot-done)] text-white',
                  isActive &&
                    'timeline-step-active bg-[var(--color-booking-step-active)] text-white shadow-[0_0_10px_var(--color-booking-step-active)]',
                  isFuture &&
                    'timeline-step-future bg-transparent border border-[var(--color-booking-step-future)] text-muted-foreground'
                )}
              >
                {isDone ? <Check className="h-3.5 w-3.5" /> : index + 1}
              </div>
              <span
                className={cn(
                  'text-[10px] font-medium whitespace-nowrap',
                  isActive && 'text-foreground',
                  isDone && 'text-[var(--color-timeline-dot-done)]',
                  isFuture && 'text-muted-foreground'
                )}
              >
                {step.label}
              </span>
            </div>
            {index < steps.length - 1 && (
              <div
                className={cn(
                  'h-px w-12 mx-1 mb-5 transition-colors duration-200',
                  index < currentStep
                    ? 'bg-[var(--color-timeline-dot-done)]'
                    : 'bg-[var(--color-timeline-line)]'
                )}
              />
            )}
          </div>
        )
      })}
    </nav>
  )
}

