}
@keyframes now-pulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50%      { transform: scale(1.2); opacity: 0.75; }
}

/* ──────────────────────────────────────────────────────────
   DARK MODE — single authoritative .dark block (Sprint 4)
   Philosophy: Linear/Notion dark — NOT pitch black.
   Background L15, card L20, border L28. Warm slate hue 264.
────────────────────────────────────────────────────────── */
.dark {
  /* ── Core semantic ── */
  --color-background:          oklch(15% 0.01 85);
  --color-foreground:          oklch(95% 0.005 85);
  --color-card:                oklch(20% 0.015 85);
  --color-card-foreground:     oklch(95% 0.005 85);
  --color-popover:             oklch(20% 0.015 85);
  --color-popover-foreground:  oklch(95% 0.005 85);

  /* Primary inverts in dark: Bone-leaning surface with Onyx-leaning text.
     Onyx-on-Bone buttons flip to Bone-on-Onyx for correct brand contrast. */
  --color-primary:             oklch(92% 0.005 85);
  --color-primary-foreground:  oklch(15% 0.01 85);

  --color-secondary:           oklch(24% 0.015 85);
  --color-secondary-foreground: oklch(88% 0.01 85);

  --color-muted:               oklch(22% 0.01 85);
  --color-muted-foreground:    oklch(66% 0.015 85);   /* raised from 60 → 66 for AA on body text */

  /* Accent — Rust tint replaces purple. Brand Book v1.0 four-color rule. */
  --color-accent:              oklch(22% 0.03 35);
  --color-accent-foreground:   oklch(72% 0.16 35);

  --color-destructive:         oklch(62% 0.22 27);     /* L62 for 4.7:1 on bg */
  --color-destructive-foreground: oklch(99% 0 0);

  /* Brand Book v1.0 — dark onyx surfaces use warm neutral hue (85). */
  --color-border:              oklch(22% 0.008 85);
  --color-input:               oklch(20% 0.007 85);
  --color-ring:                oklch(58% 0.16 35); /* rust accent */

  /* ── Surfaces (elevation ladder) ── */
  --color-page-bg:             oklch(14% 0.005 85);
  --color-header-bg:           oklch(12% 0.005 85);        /* opaque — no glassmorphism per Brand §5 */
  --color-surface-1:           oklch(20% 0.007 85);
  --color-surface-2:           oklch(24% 0.006 85);
  --color-surface-3:           oklch(28% 0.005 85);
  --color-surface-elevated:    oklch(30% 0.007 85);

  /* Dark page highlight — subtle rust whisper (not bone blowout) */
  --color-page-highlight:      oklch(22% 0.04 35 / 0.35);
  --color-page-whisper:        oklch(58% 0.16 35 / 0.04);

  /* ── Shadows (stronger alpha — dark bg absorbs shadow) ── */
  --shadow-soft:       0 1px 3px oklch(0% 0 0 / 0.3), 0 1px 2px -1px oklch(0% 0 0 / 0.22);
