export function TodayQuickActionsRow() {
  const [walkInOpen, setWalkInOpen] = useState(false)

  function handleAction(id: string) {
    if (id === 'walk-in') {
      setWalkInOpen(true)
      return
    }
    if (id === 'aftercare') {
      toast.info('Send Aftercare coming soon')
      return
    }
    if (id === 'sale') {
      toast.info('Record Sale coming soon')
      return
    }
    // deposit — navigate to payments
  }

  return (
    <>
      <div
        className="grid grid-cols-2 gap-3 sm:grid-cols-4"
        role="toolbar"
        aria-label="Today quick actions"
      >
        {ACTIONS.map((action) => {
