/* ──────────────────────────────────────────────────────────
   DARK MODE — single authoritative .dark block
   Philosophy: warm onyx at candlelight temperature — NEVER pitch-black void.
   Lifted 2% across the ladder (page L16, card L22, sidebar L13) so surfaces
   read as distinct tiles, not a single flat black. Hue 85 (warm stone) with
   mild chroma bump 0.012–0.018 for editorial warmth. Shadows carry less
   weight because the elevation ladder itself does the lifting.
────────────────────────────────────────────────────────── */
.dark {
  /* ── Core semantic ── */
  --color-background:          oklch(17% 0.013 85);
  --color-foreground:          oklch(95% 0.008 85);
  --color-card:                oklch(22% 0.015 85);
  --color-card-foreground:     oklch(95% 0.008 85);
  --color-popover:             oklch(24% 0.016 85);
  --color-popover-foreground:  oklch(95% 0.008 85);

  /* Primary inverts: Bone button surface with Onyx text (premium B2B). */
  --color-primary:             oklch(94% 0.008 85);
  --color-primary-foreground:  oklch(16% 0.012 85);

  --color-secondary:           oklch(26% 0.014 85);
  --color-secondary-foreground: oklch(90% 0.01 85);

  --color-muted:               oklch(25% 0.014 85);
  --color-muted-foreground:    oklch(72% 0.013 85);   /* AA on body copy */

  /* Accent — Rust tint (Brand Book §4.4 Rule 2: Rust is earned) */
  --color-accent:              oklch(24% 0.045 35);
  --color-accent-foreground:   oklch(74% 0.15 35);

  --color-destructive:         oklch(62% 0.22 27);
  --color-destructive-foreground: oklch(99% 0 0);

  /* Hairlines — lifted to L28 so they're visible on L22 cards */
  --color-border:              oklch(28% 0.013 85);
  --color-input:               oklch(24% 0.012 85);
  --color-ring:                oklch(58% 0.16 35);

  /* ── Elevation ladder — widened deltas (5–6% per step) so cards pop ── */
  --color-page-bg:             oklch(16% 0.012 85);   /* was 14 */
  --color-header-bg:           oklch(14% 0.012 85);   /* recessed from page */
  --color-surface-1:           oklch(22% 0.015 85);   /* = card */
  --color-surface-2:           oklch(27% 0.014 85);
  --color-surface-3:           oklch(32% 0.013 85);
  --color-surface-elevated:    oklch(36% 0.012 85);

  /* Page highlight whispers — rust warmth top-right */
  --color-page-highlight:      oklch(24% 0.045 35 / 0.32);
  --color-page-whisper:        oklch(58% 0.16 35 / 0.04);

  /* ── Chip / badge tokens (NEW) — onyx-family dark variants for pills,
     tags, status chips, and any "darker than card, clearly a tile" UI.
     Usage: bg-[var(--color-chip-bg)] text-[var(--color-chip-foreground)]
     border border-[color:var(--color-chip-border)] ── */
  --color-chip-bg:                oklch(29% 0.014 85);
  --color-chip-bg-strong:        oklch(35% 0.014 85);   /* hover/active */
  --color-chip-foreground:       oklch(90% 0.008 85);
  --color-chip-border:           oklch(35% 0.013 85);

  /* Rust-tinted chip — earned-accent pill (active state, live indicator) */
  --color-chip-rust-bg:          oklch(26% 0.08 35);
  --color-chip-rust-foreground:  oklch(80% 0.15 35);
  --color-chip-rust-border:      oklch(34% 0.1 35);

  /* Stone chip — secondary metadata, quiet labels */
  --color-chip-stone-bg:         oklch(26% 0.008 85);
  --color-chip-stone-foreground: oklch(74% 0.008 85);
  --color-chip-stone-border:     oklch(32% 0.008 85);

  /* ── Shadows — lighter alpha; ladder does the heavy lifting now ── */
  --shadow-soft:       0 1px 3px oklch(0% 0 0 / 0.22), 0 1px 2px -1px oklch(0% 0 0 / 0.14);
  --shadow-card:       0 1px 4px oklch(0% 0 0 / 0.18), 0 2px 8px -2px oklch(0% 0 0 / 0.14);
  --shadow-card-hover: 0 8px 25px oklch(0% 0 0 / 0.3), 0 0 0 1px oklch(58% 0.16 35 / 0.24), inset 0 1px 0 oklch(100% 0 0 / 0.06);
  --shadow-soft-md:    0 4px 12px -2px oklch(0% 0 0 / 0.24), 0 2px 6px -2px oklch(0% 0 0 / 0.16);
  --shadow-lift:       0 8px 24px -4px oklch(0% 0 0 / 0.5), 0 4px 10px -2px oklch(0% 0 0 / 0.3);
  --shadow-overlay:    0 24px 64px -12px oklch(0% 0 0 / 0.7), 0 8px 24px -4px oklch(0% 0 0 / 0.45);
  --shadow-glow-card:  0 1px 3px oklch(0% 0 0 / 0.16), 0 0 0 1px oklch(30% 0.015 85 / 0.6), inset 0 1px 0 oklch(100% 0 0 / 0.05);

  /* ── Status tokens — bumped saturation so chip tiles are clearly colored
     (not faded ghosts) on the lifted card background ── */
  --color-success:             oklch(64% 0.17 145);
  --color-success-bg:          oklch(24% 0.08 145);   /* was 20/0.06 */
  --color-success-foreground:  oklch(82% 0.14 145);
  --color-warning:             oklch(74% 0.16 72);
  --color-warning-bg:          oklch(26% 0.09 72);    /* was 22/0.07 */
  --color-warning-foreground:  oklch(86% 0.14 72);

  /* ── KPI accents — Rust is the brand anchor; Stone differentiates ── */
  --color-kpi-bookings:        oklch(58% 0.16 35);
  --color-kpi-revenue:         oklch(94% 0.008 85);
  --color-kpi-clients:         oklch(74% 0.013 85);
  --color-kpi-alert:           oklch(58% 0.22 27);

  /* ── Auth page — slightly deeper than app bg for focus ── */
  --color-auth-bg:             oklch(14% 0.012 85);
  --color-auth-card:           oklch(20% 0.015 85);
  --color-auth-border:         oklch(30% 0.02 85);

  /* ── Sidebar — recessed L13 (was L11). Still darker than page-bg L16 so
     chrome reads as "behind" the content area. Lifted enough to not feel
     pitch-black against the lifted content surfaces. ── */
  --sidebar:                        oklch(13% 0.012 85);
  --sidebar-background:             oklch(13% 0.012 85);
  --sidebar-foreground:             oklch(90% 0.008 85);
  --sidebar-primary:                oklch(94% 0.008 85);
  --sidebar-primary-foreground:     oklch(16% 0.012 85);
  --sidebar-accent:                 oklch(24% 0.045 35);
  --sidebar-accent-foreground:      oklch(74% 0.15 35);
  --sidebar-border:                 oklch(26% 0.013 85);
  --sidebar-ring:                   oklch(58% 0.16 35);

