  filters: Filters,
): Promise<AiDesignGalleryItem[]> {
  const params = new URLSearchParams({ studio_id: studioId })
  if (filters.style !== 'all') params.set('style', filters.style)
  if (filters.status !== 'all') params.set('status', filters.status)

  const res = await fetch(`/api/ai/requests?${params.toString()}`)
  if (!res.ok) throw new Error('Failed to load gallery')
  const json = await res.json() as { data: AiDesignGalleryItem[] }
  return json.data ?? []
}

export function DesignGallery({ studioId, onNewRequest }: Props) {
  const [filters, setFilters] = useState<Filters>({ style: 'all', status: 'all' })

  const { data: items, isLoading, isError } = useQuery({
    queryKey: ['ai-gallery', studioId, filters],
    queryFn: () => fetchGallery(studioId, filters),
    staleTime: 30_000,
  })

  function setFilter<K extends keyof Filters>(key: K, value: Filters[K]) {
    setFilters((prev) => ({ ...prev, [key]: value }))
  }

  return (
    <div className="space-y-5">
      {/* Filter toolbar — primary "New design" CTA lives in the parent
          PageHeader (AiDesignHub), so it's intentionally not duplicated here. */}
      <div className="flex flex-wrap items-center gap-2">
        <Filter size={15} strokeWidth={1.75} className="text-muted-foreground" aria-hidden="true" />
        <Select
          value={filters.style}
          onValueChange={(v) => setFilter('style', v as Filters['style'])}
        >
          <SelectTrigger className="h-9 w-44 text-sm">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {STYLE_OPTIONS.map((o) => (
              <SelectItem key={o.value} value={o.value}>
                {o.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Select
          value={filters.status}
          onValueChange={(v) => setFilter('status', v as Filters['status'])}
        >
          <SelectTrigger className="h-9 w-40 text-sm">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {STATUS_OPTIONS.map((o) => (
              <SelectItem key={o.value} value={o.value}>
                {o.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Grid */}
      <DataState
        data={items}
        isLoading={isLoading}
        isError={isError}
        loadingSlot={
          /* Masonry loading — varying heights simulate CSS columns layout */
          <div className="columns-1 sm:columns-2 lg:columns-3 xl:columns-4 gap-4">
            {(['h-48', 'h-64', 'h-56', 'h-72', 'h-48', 'h-80', 'h-56', 'h-60'] as const).map((h, i) => (
              <div key={i} className={`break-inside-avoid mb-4 rounded-xl bg-muted animate-pulse ${h}`} />
            ))}
          </div>
        }
        emptySlot={
          <EmptyState
            icon={Wand2}
            title="No designs generated"
            description="Generate tattoo concept art for your clients using the AI Design Assistant."
            cta={{ label: 'Generate design', onClick: onNewRequest }}
            variant="first-time"
          />
        }
      >
        {(data) => (
          /* CSS columns masonry — no JS dep, SSR-safe, variable-height tiles */
          <div className="columns-1 sm:columns-2 lg:columns-3 xl:columns-4 gap-4">
            {data.map((item) => (
              <DesignGalleryCard
                key={item.request.id}
                item={item}
                className="break-inside-avoid mb-4"
              />
            ))}
          </div>
        )}
      </DataState>
    </div>
  )
}

