type StudioProfileData = Pick<
  Database['public']['Tables']['studios']['Row'],
  'id' | 'name' | 'slug' | 'timezone' | 'currency' | 'locale'
>

interface StudioFormState {
  name: string
  slug: string
  timezone: string
  currency: string
}

interface StudioProfileClientProps {
  studio: StudioProfileData
  isOwner: boolean
}

export function StudioProfileClient({ studio, isOwner }: StudioProfileClientProps) {
  const [form, setForm] = useState<StudioFormState>({
    name: studio.name,
    slug: studio.slug,
    timezone: studio.timezone,
    currency: studio.currency,
  })

  const { status, lastSavedAt, handleBlur } = useDebouncedAutoSave<StudioFormState>({
    onSave: async (value) => {
      const res = await fetch('/api/studio/profile', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: value.name.trim(),
          slug: value.slug.trim(),
          timezone: value.timezone,
          currency: value.currency,
        }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        const msg = json.error ?? 'Failed to save studio profile'
        toast.error(msg)
        throw new Error(msg)
      }
    },
    delay: 800,
  })

  function update(patch: Partial<StudioFormState>) {
    setForm((prev) => ({ ...prev, ...patch }))
  }

  const readOnly = !isOwner

  return (
    <div className="space-y-10">
      {/* Page heading — editorial serif treatment + rust hairline per brand */}
      <div className="relative flex items-start justify-between gap-4 pb-4 after:pointer-events-none after:absolute after:bottom-0 after:left-0 after:h-px after:w-10 after:bg-[linear-gradient(to_right,_oklch(58%_0.16_35/_0.6),_transparent)]">
        <div>
          <h1 className="font-display text-[32px] leading-[1.1] text-foreground">
            Studio Profile
          </h1>
          <p className="mt-1.5 text-sm text-stone-brand">
            Visible to clients on your booking page.
          </p>
        </div>
        <SaveIndicator status={status} lastSavedAt={lastSavedAt} className="mt-1 shrink-0" />
      </div>

      {/* Basic info */}
      <section className="space-y-5">
        <div className="space-y-1">
          <Typography variant="h3" className="text-[17px] font-semibold tracking-tight">Basic info</Typography>
          <p className="text-sm text-stone-brand">Your studio&apos;s public name and URL slug.</p>
        </div>
        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2">
          {/* Studio name — full width */}
          <div className="sm:col-span-2 space-y-1.5">
            <Label htmlFor="studio-name">Studio name</Label>
            <Input
              id="studio-name"
              value={form.name}
              readOnly={readOnly}
              disabled={readOnly}
              maxLength={100}
              placeholder="Ink Haus Studio"
              onChange={(e) => update({ name: e.target.value })}
              onBlur={() => void handleBlur(form)}
              className={readOnly ? 'cursor-not-allowed bg-muted/50 text-muted-foreground' : undefined}
            />
          </div>

          {/* Slug — full width */}
          <div className="sm:col-span-2 space-y-1.5">
            <Label htmlFor="studio-slug">Booking page URL</Label>
            <div className="flex items-center gap-1">
              <span className="text-sm text-muted-foreground shrink-0">inkos.io/book/</span>
              <Input
                id="studio-slug"
                value={form.slug}
                readOnly={readOnly}
                disabled={readOnly}
                maxLength={60}
                placeholder="ink-haus"
                onChange={(e) => update({ slug: e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, '-') })}
                onBlur={() => void handleBlur(form)}
                className={readOnly ? 'cursor-not-allowed bg-muted/50 text-muted-foreground' : undefined}
              />
            </div>
            <p className="text-xs text-muted-foreground">
              Only lowercase letters, numbers, and hyphens. Cannot be changed after launch.
            </p>
          </div>
        </div>
      </section>

      <Separator />

      {/* Locale */}
      <section className="space-y-4">
        <div>
          <Typography variant="h3">Locale</Typography>
          <p className="text-sm text-muted-foreground">Timezone and currency used across bookings and billing.</p>
        </div>
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          {/* Timezone */}
          <div className="space-y-1.5">
            <Label htmlFor="studio-timezone">Timezone</Label>
            <select
              id="studio-timezone"
              value={form.timezone}
              disabled={readOnly}
              onChange={(e) => {
                update({ timezone: e.target.value })
              }}
              onBlur={() => void handleBlur(form)}
              className="flex h-10 w-full rounded-lg border border-input bg-[var(--color-card)] px-3 py-2 text-sm text-foreground shadow-[var(--shadow-soft)] transition-[color,background-color,border-color,box-shadow] outline-none hover:border-foreground/20 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:bg-muted/40 disabled:text-muted-foreground"
            >
              {TIMEZONES.map((group) => (
                <optgroup key={group.group} label={group.group}>
                  {group.options.map((tz) => (
                    <option key={tz.value} value={tz.value}>
                      {tz.label}
                    </option>
                  ))}
                </optgroup>
              ))}
            </select>
          </div>

          {/* Currency */}
          <div className="space-y-1.5">
            <Label htmlFor="studio-currency">Currency</Label>
            <select
              id="studio-currency"
              value={form.currency}
              disabled={readOnly}
              onChange={(e) => {
                update({ currency: e.target.value })
              }}
