              className="flex h-10 w-full rounded-lg border border-input bg-[var(--color-card)] px-3 py-2 text-sm text-foreground shadow-[var(--shadow-soft)] transition-[color,background-color,border-color,box-shadow] outline-none hover:border-foreground/20 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:bg-muted/40 disabled:text-muted-foreground"
            >
