import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { TagsManager } from '@/components/settings/tags/TagsManager'
import type { ClientTag } from '@/components/clients/TagChip'

export const metadata: Metadata = {
  title: 'Client Tags — InkOS',
}

export default async function ClientTagsSettingsPage() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  // Owner + admin only — tag management is studio-level governance.
  if (auth.role !== 'owner' && auth.role !== 'admin') redirect('/settings')

  const supabase = await createClient()

  const [tagsResult, clientTagData] = await Promise.all([
    supabase
      .from('client_tags')
      .select('id, name, color, icon, description, created_at, updated_at')
      .eq('studio_id', auth.studioId)
      .order('name'),
    supabase
      .from('clients')
      .select('tags')
      .eq('studio_id', auth.studioId)
      .is('archived_at', null),
  ])

  const rawTags = tagsResult.data ?? []
  const usageCounts: Record<string, number> = {}
  for (const client of clientTagData.data ?? []) {
    for (const tagRef of client.tags ?? []) {
      usageCounts[tagRef] = (usageCounts[tagRef] ?? 0) + 1
    }
  }

  const tagsWithCount: (ClientTag & { usage_count?: number })[] = rawTags.map((tag) => ({
    id: tag.id,
    name: tag.name,
    color: tag.color as ClientTag['color'],
    icon: tag.icon,
    description: tag.description,
    usage_count: usageCounts[tag.id] ?? usageCounts[tag.name] ?? 0,
  }))

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-lg font-semibold">Client tags</h1>
        <p className="text-sm text-muted-foreground mt-1">
          Organize your clients with tags like VIP, Allergic, or Color specialist. Tags appear on
          client rows and power the filter chips on the Clients page.
        </p>
      </div>
      <TagsManager initialTags={tagsWithCount} />
    </div>
  )
}

import type { Metadata } from 'next'
import { StyleTagsManager } from '@/components/settings/studio/StyleTagsManager'

export const metadata: Metadata = {
  title: 'Style Tags — InkOS',
}

export default function StyleTagsPage() {
  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-lg font-semibold">Style tags</h1>
        <p className="text-sm text-muted-foreground mt-1">
          Manage tags used to categorize flash designs and portfolio items.
        </p>
      </div>
      <StyleTagsManager />
    </div>
  )
}

