import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { TagsClient } from './TagsClient'
import type { ClientTag } from '@/components/clients/TagChip'

export const metadata: Metadata = {
  title: 'Tags — InkOS',
}

const VALID_TABS = ['client', 'style'] as const
type TabKey = (typeof VALID_TABS)[number]

interface PageProps {
  searchParams: Promise<{ tab?: string }>
}

export default async function TagsSettingsPage({ searchParams }: PageProps) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  // Owner + admin only — tag management is studio-level governance.
  if (auth.role !== 'owner' && auth.role !== 'admin') redirect('/settings')

  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeTab: TabKey =
    rawTab && (VALID_TABS as readonly string[]).includes(rawTab) ? (rawTab as TabKey) : 'client'

  // Prefetch client-tag data for the default tab. Style tags load their own
  // data client-side inside <StyleTagsManager /> — keeping the split avoids a
  // double query when a user only lands on one tab.
  const supabase = await createClient()

  const [tagsResult, clientTagData] = await Promise.all([
    supabase
      .from('client_tags')
      .select('id, name, color, icon, description, created_at, updated_at')
      .eq('studio_id', auth.studioId)
      .order('name'),
    supabase
      .from('clients')
      .select('tags')
      .eq('studio_id', auth.studioId)
      .is('archived_at', null),
  ])

  const rawTags = tagsResult.data ?? []
  const usageCounts: Record<string, number> = {}
  for (const client of clientTagData.data ?? []) {
    for (const tagRef of client.tags ?? []) {
      usageCounts[tagRef] = (usageCounts[tagRef] ?? 0) + 1
    }
  }

  const clientTags: (ClientTag & { usage_count?: number })[] = rawTags.map((tag) => ({
    id: tag.id,
    name: tag.name,
    color: tag.color as ClientTag['color'],
    icon: tag.icon,
    description: tag.description,
    usage_count: usageCounts[tag.id] ?? usageCounts[tag.name] ?? 0,
  }))

  return (
    <TagsClient
      activeTab={activeTab}
      clientTags={clientTags}
      currentPlan={auth.plan ?? 'solo'}
      currentRole={auth.role}
    />
  )
}

