'use client'

import { useState, useEffect } from 'react'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '@/lib/utils'
import { X, Tag } from 'lucide-react'
import type { StyleTag } from '@/lib/supabase/types'

interface StyleTagPickerProps {
  selectedIds: string[]
  onChange: (ids: string[]) => void
  disabled?: boolean
  className?: string
  /** Optional: pre-loaded tags to avoid extra fetch */
  tags?: StyleTag[]
}

export function StyleTagPicker({
  selectedIds,
  onChange,
  disabled = false,
  className,
  tags: propTags,
}: StyleTagPickerProps) {
  const [tags, setTags] = useState<StyleTag[]>(propTags ?? [])
  const [loading, setLoading] = useState(!propTags)

  useEffect(() => {
    if (propTags) {
      setTags(propTags)
      setLoading(false)
      return
    }
    const controller = new AbortController()
    fetch('/api/style-tags', { signal: controller.signal })
      .then((r) => r.json())
      .then((j: unknown) => {
        if (j && typeof j === 'object' && 'data' in j && Array.isArray((j as { data: StyleTag[] }).data)) {
          setTags((j as { data: StyleTag[] }).data)
        }
      })
      .catch(() => null)
      .finally(() => setLoading(false))
    return () => controller.abort()
  }, [propTags])

  function toggle(tagId: string) {
    if (disabled) return
    if (selectedIds.includes(tagId)) {
      onChange(selectedIds.filter((id) => id !== tagId))
    } else {
      onChange([...selectedIds, tagId])
    }
  }

  if (loading) {
    return (
      <div className={cn('flex flex-wrap gap-1.5', className)}>
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-6 w-16 rounded-full" />
        ))}
      </div>
    )
  }

  if (tags.length === 0) {
    return (
      <p className="text-xs text-muted-foreground">
        No style tags yet.{' '}
        <a href="/settings/studio/style-tags" className="underline hover:text-foreground">
          Add tags in settings.
        </a>
      </p>
    )
  }

  return (
    <div className={cn('space-y-2', className)}>
      <div className="flex flex-wrap gap-1.5">
        {tags.map((tag) => {
          const isSelected = selectedIds.includes(tag.id)
          return (
            <button
              key={tag.id}
              type="button"
              disabled={disabled}
              onClick={() => toggle(tag.id)}
              className={cn(
                'inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-xs font-medium border transition-all',
                'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                disabled && 'opacity-50 cursor-not-allowed',
                isSelected
                  ? 'border-primary bg-primary/10 text-primary'
                  : 'border-border/60 bg-muted/50 text-muted-foreground hover:border-primary/40 hover:text-foreground',
              )}
              aria-pressed={isSelected}
              aria-label={`${isSelected ? 'Remove' : 'Add'} style tag: ${tag.name}`}
            >
              {tag.color && (
                <span
                  className="h-1.5 w-1.5 rounded-full shrink-0"
                  style={{ backgroundColor: tag.color }}
                  aria-hidden="true"
                />
              )}
              {tag.name}
              {isSelected && (
                <X className="h-2.5 w-2.5 ml-0.5" aria-hidden="true" />
              )}
            </button>
          )
        })}
      </div>

      {selectedIds.length > 0 && (
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="h-6 text-xs px-2 text-muted-foreground"
          onClick={() => onChange([])}
          disabled={disabled}
        >
          Clear all
        </Button>
      )}
    </div>
  )
}

// ── Read-only chips (for display, no interaction) ─────────────────────────────

interface StyleTagChipsProps {
  tagIds: string[]
  tags: StyleTag[]
  className?: string
  maxVisible?: number
}

export function StyleTagChips({ tagIds, tags, className, maxVisible = 99 }: StyleTagChipsProps) {
  if (!tagIds.length) return null

  const matchedTags = tagIds
    .map((id) => tags.find((t) => t.id === id))
    .filter((t): t is StyleTag => !!t)
    .slice(0, maxVisible)

  const overflow = tagIds.length - maxVisible

  return (
    <div className={cn('flex flex-wrap gap-1', className)}>
      {matchedTags.map((tag) => (
        <span
          key={tag.id}
          className="inline-flex items-center gap-1 rounded-full border border-border/50 bg-muted/40 px-2 py-0.5 text-[10px] font-medium text-muted-foreground"
        >
          {tag.color && (
            <span
              className="h-1.5 w-1.5 rounded-full shrink-0"
              style={{ backgroundColor: tag.color }}
              aria-hidden="true"
            />
          )}
          {tag.name}
        </span>
      ))}
      {overflow > 0 && (
        <span className="inline-flex items-center rounded-full border border-border/50 bg-muted/40 px-2 py-0.5 text-[10px] text-muted-foreground">
          <Tag className="h-2.5 w-2.5 mr-0.5" />
          +{overflow}
        </span>
      )}
    </div>
  )
}
